def fibfib(n: int):
    if n == 0 or n == 1:
        return 0
    elif n == 2:
        return 1

    fib_fib = [0] * (n + 1)
    fib_fib[0], fib_fib[1], fib_fib[2] = 0, 0, 1

    for i in range(3, n + 1):
        fib_fib[i] = fib_fib[i - 1] + fib_fib[i - 2] + fib_fib[i - 3]

    return fib_fib[n]

