def prod_signs(shift):
    if not shift:
        return None

    sign_product = 1
    magnitude_sum = 0

    for num in shift:
        # Calculate sign product
        if num == 0:
            sign_product = 0
            break
        elif num < 0:
            sign_product *= -1

        # Calculate magnitude sum
        magnitude_sum += abs(num)

    if sign_product == 0:
        return 0
    else:
        return magnitude_sum * sign_product

