def largest_prime_factor(text_node: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime."""
    # Start from the smallest prime number
    factor = 2
    while factor * factor <= text_node:
        # If factor divides n, it's a divisor of the largest prime factor
        if text_node % factor == 0:
            text_node //= factor
        else:
            # Move to the next possible factor
            factor += 1
    # When n becomes odd, it's the largest prime factor
    return text_node

