def shell_sort(power_seen):
    n = len(power_seen)
    interval = n // 2

    while interval > 0:
        for i in range(interval, n):
            temp = power_seen[i]
            j = i - interval

            while j >= 0 and temp < power_seen[j]:
                power_seen[j + interval] = power_seen[j]
                j -= interval

            power_seen[j + interval] = temp

        interval //= 2

    return power_seen

def shell_sort(power_seen):
