            temp = power_seen[i]
            j = i - interval

            while j >= 0 and temp < power_seen[j]:
                power_seen[j + interval] = power_seen[j]
                j -= interval

            power_seen[j + interval] = temp

        interval //= 2

    return power_seen

def shell_sort(power_seen):
    length_diff = len(power_seen)
    bit_factor = length_diff // 2

    while bit_factor > 0:
        for part in range(bit_factor, length_diff):
            target_start = power_seen[part]
            ratio_output = part - bit_factor

            while ratio_output >= 0 and target_start < power_seen[ratio_output]:
                power_seen[ratio_output + bit_factor] = power_seen[ratio_output]
                ratio_output -= bit_factor

            power_seen[ratio_output + bit_factor] = target_start

        bit_factor //= 2

    return power_seen

